#!/usr/bin/env node
/**
 * patch-logos.mjs  —  byCarlo: full-colour 3D logos in the tech stack
 *
 * Keeps your exact 3D build (14 stacked layers, same hover / tap spin, same
 * stagger on tab change). What changes:
 *   - the FRONT layer is the real multi-colour logo (Python blue + yellow,
 *     TypeScript with white letters, Docker with its shading, ...)
 *   - the 13 THICKNESS layers are a silhouette of the logo in the tool's brand
 *     colour, getting darker towards the back (so it looks like solid, coloured plastic)
 *   - Next.js, Express, Vercel and GitHub are black in real life (black = invisible in
 *     dark mode), so they use your site accent colour instead (same as the preview)
 *
 * The 18 SVG logos are bundled inside this file (source: open-source "logos" set by
 * gilbarbara). No internet and no npm install needed. They are written to /public/logos.
 *
 * Usage (run from the repo root, the folder that contains /app):
 *   node patch-logos.mjs              apply
 *   node patch-logos.mjs --dry        show what would change, write nothing
 *   node patch-logos.mjs --revert     restore the backups and remove /public/logos
 *
 * Safe to run more than once. Nothing is written unless every edit matches your code.
 * Backups: <file>.bak-patch-logos
 */

import fs from "node:fs";
import path from "node:path";

const BAK = ".bak-patch-logos";
const args = process.argv.slice(2);
const DRY = args.includes("--dry");
const REVERT = args.includes("--revert");

const ROOT = process.cwd();
const FILES = { css: "app/globals.css", page: "app/page.js" };
const LOGO_DIR = "public/logos";
const abs = (rel) => path.join(ROOT, rel);
const line = (s = "") => console.log(s);

/* ── bundled logos ─────────────────────────────────────────────────────── */
