/* ── sanity: are we in the repo root? ──────────────────────────────────── */
for (const rel of Object.values(FILES)) {
  if (!fs.existsSync(abs(rel))) {
    console.error(`✖ Cannot find ${rel}. Run this script from the repo root (the folder that contains /app).`);
    process.exit(1);
  }
}

/* ── revert ────────────────────────────────────────────────────────────── */
if (REVERT) {
  let n = 0;
  for (const rel of Object.values(FILES)) {
    const bak = abs(rel) + BAK;
    if (fs.existsSync(bak)) { fs.copyFileSync(bak, abs(rel)); console.log(`↩ restored ${rel}`); n++; }
    else console.log(`· no backup for ${rel}, skipped`);
  }
  for (const key of Object.keys(LOGOS)) {
    const f = abs(`${LOGO_DIR}/${key}.svg`);
    if (fs.existsSync(f)) fs.unlinkSync(f);
  }
  try { fs.rmdirSync(abs(LOGO_DIR)); } catch {}
  console.log(n ? `\nDone. ${n} file(s) restored, logos removed.` : "\nNothing to restore.");
  process.exit(0);
}

/* ── new code blocks (written with string concatenation on purpose) ───── */
const LOGO_MAP = String.raw`
/* ── Full-colour logos ─────────────────────────────
   file  = /public/logos/<file>.svg (real multi-colour logo)
   side  = colour of the 3D thickness (darkened automatically towards the back)
   scale = optional, makes wide logos (cloud shapes) a bit bigger
   No entry = black-brand tool: plain react-icon in the site accent colour */
const TECH_LOGOS = {
  "React": { file: "react", side: "#1FB6D9" },
  "TypeScript": { file: "typescript", side: "#3178C6" },
  "Tailwind": { file: "tailwindcss", side: "#06B6D4", scale: 1.2 },
  "Node.js": { file: "nodejs", side: "#5FA04E" },
  "GraphQL": { file: "graphql", side: "#E535AB" },
  "Python": { file: "python", side: "#3776AB" },
  "Postman": { file: "postman", side: "#FF6C37" },
  "PostgreSQL": { file: "postgresql", side: "#336791" },
  "MongoDB": { file: "mongodb", side: "#47A248" },
  "Cloudflare D1": { file: "cloudflare", side: "#F38020", scale: 1.2 },
  "JWT": { file: "jwt", side: "#D63AFF" },
  "OAuth": { file: "auth0", side: "#EB5424" },
  "Cloudflare": { file: "cloudflare", side: "#F38020", scale: 1.2 },
  "Docker": { file: "docker", side: "#2396ED", scale: 1.1 },
  "Git": { file: "git", side: "#DE4C36" },
  "VS Code": { file: "vscode", side: "#007ACC" },
  "ESLint": { file: "eslint", side: "#4B32C3" },
  "Jest": { file: "jest", side: "#C21325" },
  "npm": { file: "npm", side: "#CB3837" },
};`;

const ICON3D = String.raw`function Icon3D({ Icon, logo, brand, scale = 1, size = ICON3D_SIZE, autoSpin = false, index = 0 }) {
  // one turn per hover (mouse) or tap (touch); ignored while it is already turning
  // autoSpin: the icon mounts already turning (used when the category changes)
  // logo: path to a full-colour SVG (front layer) - its silhouette becomes the thickness
  // brand: colour of the thickness (any CSS colour or var)
  const [spinning, setSpinning] = useState(autoSpin);
  const [autoDelay, setAutoDelay] = useState(autoSpin ? index * ICON3D_STAGGER_MS : 0);
  const step = (size * ICON3D_THICKNESS) / (ICON3D_DEPTH - 1);
  const half = (ICON3D_DEPTH - 1) / 2; // centers the thickness on z=0 so it spins around its own middle
  const px = Math.round(size * scale);
  const maskUrl = logo ? "url(" + logo + ")" : undefined;
  const layers = [];
  for (let k = ICON3D_DEPTH - 1; k >= 0; k--) {
    // thickness = brand colour, mixed with more black towards the back (22% -> 52%)
    const dark = Math.round(22 + (k / (ICON3D_DEPTH - 1)) * 30);
    const side = "color-mix(in srgb, " + brand + " " + (100 - dark) + "%, black)";
    let content;
    if (logo) {
      content = k === 0
        ? <img src={logo} alt="" width={px} height={px} draggable={false} className="ts-icon3d-img" />
        : <span className="ts-icon3d-sil" style={{ width: px, height: px, background: side, WebkitMaskImage: maskUrl, maskImage: maskUrl }} />;
    } else {
      content = <Icon size={size} />;
    }
    layers.push(
      <span
        key={k}
        className="ts-icon3d-layer"
        style={{
          color: k === 0 ? brand : side,
          transform: "translateZ(" + ((half - k) * step).toFixed(2) + "px)",
        }}
      >
        {content}
      </span>
    );
  }
  return (
    <span className="ts-icon3d-hit" onPointerEnter={() => { setAutoDelay(0); setSpinning(true); }}>
      <span className="ts-icon3d-wrap" aria-hidden="true" style={{ width: size, height: size, perspective: size * 15 }}>
        <span
          className={"ts-icon3d" + (spinning ? " is-spinning" : "")}
          style={autoDelay ? { animationDelay: autoDelay + "ms" } : undefined}
          onAnimationEnd={(e) => { if (e.target === e.currentTarget) { setSpinning(false); setAutoDelay(0); } }}
        >
          {layers}
        </span>
      </span>
    </span>
  );
}

`;

const CALL_SITE = String.raw`<Icon3D
                Icon={tool.Icon}
                size={ICON3D_SIZE}
                autoSpin={switched.current}
                index={toolIndex}
                logo={(TECH_LOGOS[tool.name] || {}).file ? "/logos/" + TECH_LOGOS[tool.name].file + ".svg" : undefined}
                brand={(TECH_LOGOS[tool.name] || {}).side || "var(--ic-accent)"}
                scale={(TECH_LOGOS[tool.name] || {}).scale || 1}
              />`;

const CSS_ADD = String.raw`

/* Full-colour 3D logos: front = real logo, thickness = brand-coloured silhouette */
.ts-icon3d-img {
  display: block;
  object-fit: contain;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-user-drag: none;
}
.ts-icon3d-sil {
  display: block;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
}
`;

/* ── edits ─────────────────────────────────────────────────────────────── *
 * find: string | RegExp   to: string   done: (text) => already applied?
 * ──────────────────────────────────────────────────────────────────────── */
const edits = {
  page: [
    {
      id: "Add the TECH_LOGOS map (file + thickness colour per tool)",
      find: 'const NEAR_BLACK_BRANDS = ["#000000", "#181717"];',
      to: 'const NEAR_BLACK_BRANDS = ["#000000", "#181717"];\n' + LOGO_MAP,
      done: (t) => t.includes("const TECH_LOGOS"),
    },
    {
      id: "Icon3D: real logo on the front, brand-coloured silhouette for the thickness",
      find: /function Icon3D\(\{[\s\S]*?\n\}\n\n(?=function TechStack)/,
      to: ICON3D,
      done: (t) => t.includes("ts-icon3d-sil"),
    },
    {
      id: "Icon3D call: pass logo / brand colour / scale",
      find: /<Icon3D\s+Icon=\{tool\.Icon\}[\s\S]*?\/>/,
      to: CALL_SITE,
      done: (t) => t.includes("TECH_LOGOS[tool.name]"),
    },
    {
      id: "Icon grid: expose the site accent colour as --ic-accent (for the black brands)",
      find: '"--ic-b": iconSideB }}',
      to: '"--ic-b": iconSideB, "--ic-accent": accentColor }}',
      done: (t) => t.includes('"--ic-accent"'),
    },
  ],
  css: [
    {
      id: "CSS for the logo face and silhouette layers",
      find: /$(?![\s\S])/,
      to: CSS_ADD,
      done: (t) => t.includes(".ts-icon3d-sil"),
    },
  ],
};

/* ── apply (in memory first) ───────────────────────────────────────────── */
const count = (text, f) => (typeof f === "string" ? text.split(f).length - 1 : (text.match(new RegExp(f.source, f.flags.includes("g") ? f.flags : f.flags + "g")) || []).length);

let failed = false;
let applied = 0;
const pending = [];

for (const [key, list] of Object.entries(edits)) {
  const rel = FILES[key];
  const original = fs.readFileSync(abs(rel), "utf8");
  const eol = original.includes("\r\n") ? "\r\n" : "\n";
  let text = original.replace(/\r\n/g, "\n");
  const before = text;
  line(`\n${rel}`);

  for (const e of list) {
    if (e.done(text)) { line(`  · already applied: ${e.id}`); continue; }
    const n = count(text, e.find);
    if (n !== 1) {
      line(`  ✖ ${e.id}  (found ${n} match(es), expected 1)`);
      failed = true;
      continue;
    }
    text = text.replace(e.find, () => e.to);
    line(`  ✔ ${e.id}`);
    applied++;
  }
  if (text !== before) pending.push({ rel, original, next: text.replace(/\n/g, eol) });
}

/* ── logos ─────────────────────────────────────────────────────────────── */
const logoWrites = Object.entries(LOGOS).filter(([key, svg]) => {
  const f = abs(`${LOGO_DIR}/${key}.svg`);
  return !(fs.existsSync(f) && fs.readFileSync(f, "utf8") === svg);
});
line(`\n${LOGO_DIR}/`);
line(logoWrites.length ? `  ✔ ${logoWrites.length} of ${Object.keys(LOGOS).length} logo file(s) will be written` : "  · all logos already in place");

/* ── write (all-or-nothing) ────────────────────────────────────────────── */
line("");
if (failed) {
  console.error("✖ One or more edits could not be matched. No files were changed.");
  console.error("  Send me the latest repo (or the lines named above) and I will adjust the patch.");
  process.exit(1);
}
if (!pending.length && !logoWrites.length) {
  console.log("✔ Nothing to do. Everything is already applied.");
  process.exit(0);
}
if (DRY) {
  console.log(`Dry run: ${applied} edit(s) in ${pending.length} file(s) and ${logoWrites.length} logo(s) would be written. Nothing written.`);
  process.exit(0);
}

for (const p of pending) {
  const bak = abs(p.rel) + BAK;
  if (!fs.existsSync(bak)) fs.writeFileSync(bak, p.original); // keep the FIRST original only
  fs.writeFileSync(abs(p.rel), p.next);
}
if (logoWrites.length) {
  fs.mkdirSync(abs(LOGO_DIR), { recursive: true });
  for (const [key, svg] of logoWrites) fs.writeFileSync(abs(`${LOGO_DIR}/${key}.svg`), svg);
}

console.log(`✔ Done. ${applied} edit(s) in ${pending.length} file(s), ${logoWrites.length} logo(s) written.`);
console.log(`  Backups: <file>${BAK}   (undo everything with: node patch-logos.mjs --revert)`);
console.log("");
console.log("Next: npm run dev, open the Tech stack section, click through all six tabs, hover / tap the icons,");
console.log("and check light AND dark mode.");
